  let lngLat = geodesicFromUnitVector(vector);
  // Keep longitudes continuous with the start point (unwrapped across the antimeridian).
  return vec2<f32>(a.x + geodesicWrapLongitudeDelta(lngLat.x - a.x), lngLat.y);
