  momentA = vec3<f32>(2.0 * uwu, 2.0 * wuwwu, uwwu + wu2) * scale;
  momentB = vec3<f32>(-wu2, -wwu2, -wuwwu) * scale;
  momentG = vec3<f32>(u2, wu2, uwu) * scale;
